import {P} from './palette.js';
import {oval,line,leaf,star,shadow} from './shapes.js';
import {clamp,easeOut,seed} from './animation.js';
export function drawSun(c,s,T,time,hover){const age=s.age||0,spawn=clamp(age/.6),bank=s.bank?clamp((s.amount-s.baseAmount)/20):0,x=s.x*T,y=s.y*T,sourceRise=s.source==='sunflower'?Math.sin(spawn*Math.PI)*16:-(1-easeOut(spawn))*23,reaction=s.magnetized?clamp(1-(s.magnetAge||0)/.22):0;if(s.magnetized){const vx=(s.magnetVelocityX||0)*T,vy=(s.magnetVelocityY||0)*T;c.save();c.globalAlpha=.16;line(c,[[x-vx*.055,y-vy*.055],[x,y]],P.sun,5);c.restore()}shadow(c,x,y+13,12);c.save();c.translate(x+Math.sin(time*42+s.id)*reaction*2,y+sourceRise+Math.sin(time*2+s.id)*2+Math.cos(time*38+s.id)*reaction*1.5);const pulse=1+reaction*.12;c.scale((.7+.3*easeOut(spawn))*(1+bank*.2)*pulse,(.7+.3*easeOut(spawn))*(1+bank*.2)*pulse);const expiring=s.lifetime-age<3;c.globalAlpha=expiring?.7+Math.sin(time*9)*.25:1;oval(c,0,0,23,23,P.shadow,false);c.globalAlpha*=s.magnetized?.24:.16;oval(c,0,0,25+(hover?3:0)+Math.sin(time*3),25,P.sun,false);c.globalAlpha=expiring?.75+Math.sin(time*9)*.2:1;c.save();c.rotate(time*.25+s.id);for(let i=0;i<8;i++){c.rotate(Math.PI/4);leaf(c,0,-10,6,Math.PI,P.sun)}c.restore();oval(c,0,0,12,12,P.sun);oval(c,-3,-4,6,4,P.critical,false);if(bank||expiring||s.magnetized)for(let i=0;i<3;i++){const a=time+i*2.1;star(c,Math.cos(a)*21,Math.sin(a)*21,2+bank,P.cream,a)}c.font='bold 10px system-ui';c.textAlign='center';c.fillStyle=P.bark;c.fillText(s.amount,0,5);c.restore()}
export function drawZone(c,z,T,time){const x=z.x*T,y=z.y*T,r=Math.max(3,z.r*T);c.save();c.translate(x,y);c.globalAlpha=clamp(z.t*3)*.8;if(z.type==='fire'){oval(c,0,0,r,r*.72,P.soil,false);for(let i=0;i<9;i++){const a=i*2.399,rr=Math.sqrt(seed(i+z.x))*r*.8,px=Math.cos(a)*rr,py=Math.sin(a)*rr;const h=7+Math.sin(time*7+i)*3;c.beginPath();c.moveTo(px-4,py+3);c.bezierCurveTo(px-7,py-5,px+2,py-h,px,py-h-6);c.bezierCurveTo(px+10,py-4,px+7,py+4,px-4,py+3);c.fillStyle=i%2?P.fire:P.gold;c.fill();leaf(c,px,py,4,0,P.sun)}}else if(z.type==='slow'){oval(c,0,0,r,r*.8,P.slow,false);for(let i=0;i<9;i++){const a=i*2.4,rr=seed(i+4)*r;leaf(c,Math.cos(a)*rr,Math.sin(a)*rr*.7,5,a,P.dark)}c.strokeStyle=P.light;c.lineWidth=1;c.beginPath();c.ellipse(0,0,r*(.6+.08*Math.sin(time*2)),r*.5,0,0,Math.PI*2);c.stroke()}else if(z.type==='toxic'){oval(c,0,0,r,r*.7,P.green,false);c.globalAlpha*=.7;for(let i=0;i<7;i++){const a=i*2.4+time,rr=seed(i+7)*r*.8;oval(c,Math.cos(a)*rr,Math.sin(a)*rr*.55,4+seed(i)*4,3+seed(i)*3,i%2?P.light:P.heal,false)}}else if(z.type==='blast'){oval(c,0,2,8,5,P.soil);oval(c,0,0,6,5,P.wood);line(c,[[0,-3],[2,-9]],P.dark,2);star(c,2,-10,3,P.sun,time*6)}else{oval(c,0,0,r,r*.7,P.evolution,false)}c.restore()}
export function effectFamily(e){if(e.label==='CRUSH')return'boss';if(e.label==='BOSS DOWN')return'bossDeath';if(e.label==='VOLATILE')return'explosion';if(e.label==='HEAVY'||e.label==='COMBO'||e.label==='ARMOR')return'heavy';if(e.label==='CRIT')return'critical';if(e.label==='HEAL')return'heal';if(e.color==='#ff9d39'||e.color==='#f5a13c')return'explosion';if(e.color==='#f2cb63')return'siege';if(e.color==='#b1df65')return'cabbage';if(e.color==='#e9f0a2')return'melee';if(e.label?.startsWith('+')||e.label==='STOLEN')return'sun';return'leaf'}
export function drawEffect(c,e,T,time){const p=1-clamp(e.t/e.max),r=Math.max(4,e.r*T),f=effectFamily(e);c.save();c.translate(e.x*T,e.y*T);c.globalAlpha=1-p;if(['explosion','boss','bossDeath','siege'].includes(f)){const spread=easeOut(p)*r;for(let i=0;i<7;i++){const a=i*2.4;oval(c,Math.cos(a)*spread*.55,Math.sin(a)*spread*.35,8+p*12,7+p*10,P.cream,false)}if(p<.4)star(c,0,0,r*(1-p),P.sun,p);c.strokeStyle=P.gold;c.lineWidth=4*(1-p);c.beginPath();c.ellipse(0,6,Math.max(1,spread),Math.max(1,spread*.6),0,0,Math.PI*2);c.stroke()}else if(f==='heavy'||f==='critical'||f==='melee'){star(c,0,-4,r*(.4+p*.5),f==='critical'?P.sun:P.cream,p*.5);for(let i=0;i<5;i++){const a=i*1.25;line(c,[[Math.cos(a)*r*.55,Math.sin(a)*r*.55],[Math.cos(a)*r,Math.sin(a)*r]],P.gold,2)}}else if(f==='cabbage'){for(let i=0;i<7;i++){const a=i*2.4;leaf(c,Math.cos(a)*r*p,Math.sin(a)*r*p,6*(1-p)+2,a,P.green)}}else if(f!=='sun'){leaf(c,-p*12,-p*16,6, p,P.light)}if(e.label&&(f==='sun'||f==='critical'||f==='heavy'||f==='boss')){c.font='bold 13px system-ui';c.textAlign='center';c.strokeStyle=P.cream;c.lineWidth=3;c.strokeText(e.label,0,-18-p*16);c.fillStyle=P.bark;c.fillText(e.label,0,-18-p*16)}c.restore()}
